function weaveList(head: ListNode | null): void {
  let cur = head;
  while (cur && cur.next && cur.next.next) {
    let beforeTail = cur;
    while (beforeTail.next!.next) beforeTail = beforeTail.next!;
    const tail = beforeTail.next!;
    beforeTail.next = null;
    tail.next = cur.next;
    cur.next = tail;
    cur = tail.next;
  }
}

