function weaveList(head: ListNode | null): void {
  const nodes: ListNode[] = [];
  for (let n = head; n; n = n.next) nodes.push(n);
  let i = 0, j = nodes.length - 1;
  while (i < j) {
    nodes[i].next = nodes[j];
    i++;
    if (i === j) break;
    nodes[j].next = nodes[i];
    j--;
  }
  if (nodes.length) nodes[i].next = null; // the middle node is the new tail
}

