function weaveList(head: ListNode | null): void {
  if (!head || !head.next) return;
  let slow = head, fast = head;
  while (fast.next && fast.next.next) {
    slow = slow.next!;
    fast = fast.next.next;
  }
  // reverse the back half and cut it off
  let second: ListNode | null = slow.next, prev: ListNode | null = null;
  slow.next = null;
  while (second) {
    const nxt: ListNode | null = second.next;
    second.next = prev;
    prev = second;
    second = nxt;
  }
  let first: ListNode | null = head;
  second = prev;
  while (second) {
    const a: ListNode | null = first!.next, b: ListNode | null = second.next;
    first!.next = second;
    second.next = a;
    first = a;
    second = b;
  }
}

